CREATE TABLE public.appels_mensuels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinique_id uuid NOT NULL REFERENCES public.cliniques(id), mois date NOT NULL, appels integer NOT NULL CHECK (appels >= 0), reference_appels integer NOT NULL CHECK (reference_appels >= 0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(clinique_id, mois), CHECK (extract(day from mois)=1));
GRANT SELECT, INSERT, UPDATE ON public.appels_mensuels TO authenticated;
GRANT ALL ON public.appels_mensuels TO service_role;
ALTER TABLE public.appels_mensuels ENABLE ROW LEVEL SECURITY;
CREATE POLICY appels_admin ON public.appels_mensuels FOR ALL TO authenticated USING(public.is_staff_admin()) WITH CHECK(public.is_staff_admin());
ALTER TABLE public.notifications ADD COLUMN rendez_vous_id uuid REFERENCES public.rendez_vous(id) ON DELETE CASCADE;
ALTER TABLE public.notifications ADD COLUMN categorie text NOT NULL DEFAULT 'information';
CREATE UNIQUE INDEX notification_rappel_unique ON public.notifications(rendez_vous_id,categorie) WHERE categorie='rappel';
CREATE INDEX documents_patient_idx ON public.documents(patient_id);
CREATE INDEX rendez_vous_patient_idx ON public.rendez_vous(patient_id);
CREATE INDEX notifications_user_idx ON public.notifications(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.dispatch_rappels(_now timestamptz DEFAULT now()) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.notifications(user_id,message,rendez_vous_id,categorie) SELECT patient_id,'Rappel : rendez-vous le ' || to_char(debut AT TIME ZONE 'Africa/Tunis','DD/MM/YYYY à HH24:MI'),id,'rappel' FROM public.rendez_vous WHERE statut='confirme' AND debut>_now AND debut<=_now+interval '24 hours' ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.dispatch_rappels(timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.dispatch_rappels(timestamptz) TO service_role;
REVOKE ALL ON FUNCTION public.record_login(text,boolean) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.login_locked(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_login(text,boolean),public.login_locked(text) TO service_role;
CREATE OR REPLACE FUNCTION public.log_access(_action text,_cible text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'non authentifié'; END IF; IF _action IN ('dossier_consulte','document_consulte') THEN IF NOT (_cible=auth.uid()::text OR public.is_my_patient(_cible::uuid)) THEN RAISE EXCEPTION 'accès refusé'; END IF; ELSIF _action='export_stats' THEN IF NOT public.is_staff_admin() THEN RAISE EXCEPTION 'accès refusé'; END IF; ELSIF _action='mfa_valide' THEN IF NOT public.is_aal2() THEN RAISE EXCEPTION 'MFA requise'; END IF; ELSE RAISE EXCEPTION 'action non autorisée'; END IF; INSERT INTO public.audit_logs(actor_id,action,cible) VALUES(auth.uid(),_action,left(_cible,120)); END $$;
REVOKE ALL ON FUNCTION public.log_access(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.log_access(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.doc_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(trim(NEW.titre)) NOT BETWEEN 1 AND 150 OR length(trim(NEW.contenu)) NOT BETWEEN 5 AND 10000 THEN RAISE EXCEPTION 'document invalide'; END IF; IF NEW.rendez_vous_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.rendez_vous r WHERE r.id=NEW.rendez_vous_id AND r.patient_id=NEW.patient_id AND r.praticien_id=NEW.praticien_id) THEN RAISE EXCEPTION 'rendez-vous incompatible'; END IF; RETURN NEW; END $$;
CREATE TRIGGER doc_validate_trg BEFORE INSERT ON public.documents FOR EACH ROW EXECUTE FUNCTION public.doc_validate();
CREATE OR REPLACE FUNCTION public.rdv_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.patient_id IS DISTINCT FROM OLD.patient_id OR NEW.praticien_id IS DISTINCT FROM OLD.praticien_id OR NEW.clinique_id IS DISTINCT FROM OLD.clinique_id OR NEW.debut IS DISTINCT FROM OLD.debut OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.motif IS DISTINCT FROM OLD.motif OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Modification non autorisée'; END IF; IF auth.uid()=OLD.patient_id AND NOT public.is_staff_admin() AND (OLD.statut<>'confirme' OR NEW.statut<>'annule') THEN RAISE EXCEPTION 'Modification non autorisée'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.role_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,cible,details) VALUES(auth.uid(),'role_modifie',coalesce(NEW.user_id,OLD.user_id)::text,jsonb_build_object('operation',TG_OP,'role',coalesce(NEW.role,OLD.role))); RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER role_audit_trg AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.role_audit();
CREATE OR REPLACE FUNCTION public.appels_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,cible,details) VALUES(auth.uid(),'appels_releves',NEW.clinique_id::text,jsonb_build_object('mois',NEW.mois,'appels',NEW.appels,'reference',NEW.reference_appels)); RETURN NEW; END $$;
CREATE TRIGGER appels_audit_trg AFTER INSERT OR UPDATE ON public.appels_mensuels FOR EACH ROW EXECUTE FUNCTION public.appels_audit();
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'patient'); INSERT INTO public.audit_logs(actor_id,action,cible) VALUES(NEW.id,'compte_cree',NEW.id::text); RETURN NEW; END $$;